# pocklington_export.py -- serialise an own Pocklington/trial-division certificate for EVERY prime in
# results.json (both r and every factor of r-1, r+1), then re-verify each FROM THE SERIALISED JSON with a
# string-parsing verifier (no library imports in the verifier).
import sys, json
src = open("census.py").read(); prefix = src.split("results = {", 1)[0]
sys.argv = ["census.py", "pins.json"]; g = {"__name__": "census_prefix"}
exec(compile(prefix, "census.py[prefix]", "exec"), g)
make_cert = g["make_cert"]
res = json.load(open("results.json"))
primes = []
for cid, c in res["curves"].items():
    primes.append(int(c["r_decimal"]))
    for b in c["branches"].values():
        primes += [int(f["prime"]) for f in b["factorization"]]
memo = {}
def ser(c):
    if c["method"] == "trial_division": return {"n": str(c["n"]), "method": "trial_division"}
    return {"n": str(c["n"]), "method": c["method"], "F_factors": [[str(q), e] for q, e in c["F_factors"]],
            "witnesses": {str(k): v for k, v in c["witnesses"].items()}, "sub": [ser(s) for s in c["sub"]]}
certs = {str(p): ser(make_cert(p, memo)) for p in sorted(set(primes))}
blob = json.dumps(certs)
# ---- independent verifier on the serialised form ----
from math import gcd
def V(c):
    n = int(c["n"])
    if c["method"] == "trial_division":
        if n < 2: return False
        k = 2
        while k * k <= n:
            if n % k == 0: return False
            k += 1
        return True
    F = 1
    for q, e in c["F_factors"]: F *= int(q) ** int(e)
    if (n - 1) % F or F * F <= n: return False
    subs = {int(s["n"]): s for s in c["sub"]}
    for q, e in c["F_factors"]:
        q = int(q); a = int(c["witnesses"][str(q)])
        if pow(a, n - 1, n) != 1 or gcd(pow(a, (n - 1) // q, n) - 1, n) != 1: return False
        if q not in subs or not V(subs[q]): return False
    return True
back = json.loads(blob)
ok = {p: V(c) for p, c in back.items()}
for p, v in ok.items(): print(int(p).bit_length(), "bits", p[:24] + ("..." if len(p) > 24 else ""), "verified_from_json:", v)
print("ALL CERTIFICATES VERIFY FROM SERIALISED FORM:", all(ok.values()), "| count:", len(ok))
json.dump(certs, open("pocklington_certs.json", "w"), indent=0)

