#!/bin/sh
# toolcheck.sh -- which factoring / primality / precision tools exist on this machine
for t in gp sage magma ecm yafu cado-nfs.py msieve primo openssl python3 pip3; do printf "%s: " $t; command -v $t || echo "absent"; done
python3 --version
python3 - <<'PY'
import importlib
for m in ["sympy","gmpy2","mpmath","cypari2","flint","primefac","sage","Crypto","cryptography","numpy"]:
    try:
        mod=importlib.import_module(m); print(m, getattr(mod,"__version__", getattr(mod,"version","?")))
    except Exception as e:
        print(m, "ABSENT", type(e).__name__)
PY
nproc; free -g | head -2; uname -a
